begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('11111111-1111-4111-8111-111111111111','pause@example.invalid',now()),('22222222-2222-4222-8222-222222222222','other@example.invalid',now());
insert into public.profiles(id,username) values('11111111-1111-4111-8111-111111111111','PauseTester'),('22222222-2222-4222-8222-222222222222','OtherTester');
create temp table results(name text primary key,result jsonb);grant all on results to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select is(public.begin_attempt('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',400),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'::uuid,'Client request ID is the attempt ID');
select public.begin_attempt('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',800);
insert into results values('pause',public.record_online_attempt('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":100,"usedPause":true,"events":[]}'));
select is((select (result->>'dnf')::boolean from results where name='pause'),true,'Paused single is DNF even when playback has removed pause events');
select is((select result->>'invalid_reason' from results where name='pause'),'pause','Server labels the pause DNF reason');
select is(public.my_leaderboard_candidates(),'[]'::jsonb,'Paused result never becomes an eligible single');
select lives_ok($$select public.record_online_attempt('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":100,"usedPause":true,"events":[]}')$$,'Lost finish response can be retried with identical evidence');
select throws_ok($$select public.record_online_attempt('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":90,"events":[]}')$$,'P0001','Attempt missing or already submitted','Retries cannot change a recorded result or remove its pause');
set local role postgres;
select is((select count(*)::integer from public.attempts),1,'Repeated start/finish creates exactly one attempt');
select is((select invalid_reason from public.attempts),'pause','Pause eligibility is permanent');
select is((select count(*)::integer from public.recording_objects),0,'Paused single does not consume a recording payload');
select is((select extract(epoch from (clock_timestamp()-started_at))*1000>=400 from public.attempts),true,'Start delay compensates for a brief retry without moving an existing start');
set local role authenticated;
select public.record_online_attempt(public.begin_attempt('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),jsonb_build_object('format','fto-replay-v1','size',3,'complete',true,'solveMs',n,'events','[]'::jsonb)) from unnest(array[110,120,130,140]) n;
select is((select (e->>'ms')::double precision from jsonb_array_elements(public.my_leaderboard_candidates()) e where e->>'metric'='ao5'),130::double precision,'A paused solve remains a trimmed DNF in the same ao5 sequence');
select public.record_online_attempt(public.begin_attempt('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":100,"usedPause":false,"events":[{"type":"pause"}]}');
set local role postgres;
select is((select invalid_reason from public.attempts order by started_at desc limit 1),'pause','Legacy pause events are detected even when the client flag is false');
set local role authenticated;
insert into results values('retry-single',public.record_online_attempt(public.begin_attempt('cccccccc-cccc-4ccc-8ccc-cccccccccccc'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":80,"events":[]}'));
set local role postgres;
insert into results values('receipt',(select jsonb_build_object('id',id) from public.attempts where session_id='cccccccc-cccc-4ccc-8ccc-cccccccccccc'));
set local role authenticated;
select lives_ok($$select public.record_online_attempt((select (result->>'id')::uuid from results where name='receipt'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":80,"events":[]}')$$,'Eligible finished recording retries are idempotent too');
select is((select e->>'id' from results r,jsonb_array_elements(r.result->'candidates') e where r.name='retry-single' and e->>'metric'='single'),(select e->>'id' from jsonb_array_elements(public.my_leaderboard_candidates()) e where e->>'metric'='single'),'Finish retry preserves the original submission candidate ID');
select public.skip_online_scramble('dddddddd-dddd-4ddd-8ddd-dddddddddddd','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee');
select public.skip_online_scramble('dddddddd-dddd-4ddd-8ddd-dddddddddddd','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee');
set local role postgres;
select is((select count(*)::integer from public.attempts where session_id='dddddddd-dddd-4ddd-8ddd-dddddddddddd'),1,'Retrying a skip adds only one hidden DNF');
set local role authenticated;
select throws_ok($$select public.begin_attempt('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','ffffffff-ffff-4fff-8fff-ffffffffffff',5001)$$,'P0001','Invalid attempt request','Backdating cannot exceed the five-second grace');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select throws_ok($$select public.begin_attempt('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',0)$$,'P0001','Invalid attempt request','Another user cannot reuse an attempt receipt');
select throws_ok($$select public.record_online_attempt('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',null)$$,'P0001','Attempt missing or already submitted','Another user cannot finish or retrieve an attempt');
select * from finish();rollback;
